public class StackDemo {
    public void doStuff() {
        boolean b = true;      // 在 doStuff 的栈帧里
        go(4);                 // go 被压到栈顶，doStuff 暂时被压在下面
        System.out.println("回到 doStuff，b = " + b);   // go 弹走后，b 又可见
    }
    public void go(int x) {
        int z = x + 24;        // 参数 x、局部变量 z 都在 go 的栈帧里
        crazy();               // crazy 被压到最顶上
        System.out.println("回到 go，z = " + z);
    }
    public void crazy() {
        char c = 97;           // 在 crazy 的栈帧里，方法一结束 c 就没了
    }
    public void read() {
        int s = 42;
        sleep();
        System.out.println(s); // 回到 read，s 又可见了
    }
    public void sleep() {
        // s = 7;  // 编译错误：sleep 的栈帧里根本没有 s
    }
}

