public class GcDemo {
    public static void main(String[] args) {
        Duck a = new Duck();
        Duck b = new Duck();
        a = b;                 // 第一只鸭子不再可达 → 有资格被 GC
        b = null;              // 第二只也不可达 → 有资格被 GC

        Node n1 = new Node();
        Node n2 = new Node();
        n1.next = n2;
        n2.next = n1;          // 互相引用成环
        n1 = null;
        n2 = null;             // 但从根走不到 → 环也能一起回收

        System.gc();           // 只是建议，不保证立刻执行、不保证回收谁
    }
}

