    public Boo(String s) { }
    public Boo(String s, int i) { }
    // 没有无参构造器！
}
class SonOfBoo extends Boo {
    public SonOfBoo() { super("boo"); }              // OK → Boo(String)
    public SonOfBoo(int i) { super("Fred"); }        // OK → Boo(String)
    public SonOfBoo(String s) { super(42); }         // OK → Boo(int)
    public SonOfBoo(int i, String s) { }             // 失败：补 super() 但无 Boo()
    public SonOfBoo(String a,String b,String c) { super(a,b); } // 失败：无 Boo(String,String)
    public SonOfBoo(int i, int j) { super("man", j); }// OK → Boo(String,int)
    public SonOfBoo(int i,int x,int y) { super(i,"star"); } // 失败：无 Boo(int,String)
}

class Demo {
  public static void main(String[] args) {
    Dog a = new Dog();   // 堆上造对象1，a 引用它
    Dog b = new Dog();   // 堆上造对象2，b 引用它
    a = b;               // a 改指对象2；对象1没人引用了
    // 此时对象1不可达，符合 GC 条件（何时回收由 JVM 决定）
    b = null;            // b 也不引用了；对象2只剩 a 引用
  }
}
// 关键点：断掉最后一个引用 = 对象变成垃圾
